using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evaluation;

public class EvaluationTests : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder _appBuilder = null!;
    private DistributedApplication _app = null!;

    public async ValueTask InitializeAsync()
    {
        _appBuilder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appBuilder.BuildAsync();
        await _app.StartAsync();
    }

    public async ValueTask DisposeAsync()
    {
        await _app.DisposeAsync();
    }

    [Fact]
    public async Task Greeting_ReturnsCoherentResponse()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var response = await chatClient.GetResponseAsync("Hello, how are you?");

        Assert.NotNull(response);
        Assert.NotEmpty(response.Text);
    }

    [Fact]
    public async Task FactualQuestion_ReturnsCorrectAnswer()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var response = await chatClient.GetResponseAsync("What is the capital of France?");

        Assert.NotNull(response);
        Assert.Contains("Paris", response.Text, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task MultiTurn_RetainsContext()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice."),
        };

        var firstResponse = await chatClient.GetResponseAsync(messages);
        messages.AddRange(firstResponse.Messages);
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var secondResponse = await chatClient.GetResponseAsync(messages);

        Assert.NotNull(secondResponse);
        Assert.Contains("Alice", secondResponse.Text, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task QualityEvaluation_MeetsThresholds()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what an API gateway is in one sentence."),
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        var coherenceEvaluator = new CoherenceEvaluator();
        var relevanceEvaluator = new RelevanceEvaluator();

        var evaluators = new IEvaluator[] { coherenceEvaluator, relevanceEvaluator };

        var results = await EvaluationExtensions.EvaluateAsync(
            evaluators,
            messages,
            chatClient);

        foreach (var result in results)
        {
            if (result.Value is NumericMetric numericMetric)
            {
                Assert.True(
                    numericMetric.Value >= 3.0,
                    $"Metric '{result.Key}' scored {numericMetric.Value}, below threshold of 3.0");
            }
        }
    }
}

